    child.stderr?.on('data', onData)
    child.once('exit', code => {
      if (!settled) {
        settled = true
        clearTimeout(timer)
        reject(new Error(`Vite exited before ready with code ${code}`))
      }
    })
  })
}

function connect(protocols?: string[]): Promise<WebSocket> {
  return new Promise((resolve, reject) => {
    const ws = new WebSocket('ws://127.0.0.1:5173/ws', protocols, {
      headers: { Origin: 'http://127.0.0.1:5173' },
    })
    const timer = setTimeout(() => {
      ws.terminate()
      reject(new Error('connect timeout'))
    }, 5000)
    ws.once('open', () => {
      clearTimeout(timer)
      resolve(ws)
    })
    ws.once('error', error => {
      clearTimeout(timer)
      reject(error)
    })
    ws.once('unexpected-response', (_req, res) => {
      clearTimeout(timer)
      reject(new Error(`unexpected response ${res.statusCode}`))
    })
  })
}

function nextJson(ws: WebSocket): Promise<unknown> {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('message timeout')), 5000)
    ws.once('message', raw => {
      clearTimeout(timer)
      resolve(JSON.parse(String(raw)))
    })
  })
}

